export default async function Dashboard() {
  const sessions = [{ id: '1', topic: 'Routing', minutes: 45 }];
  return <main><h1>Dashboard</h1><form action={createSession}><label htmlFor="topic">Topic</label><input id="topic" name="topic" required /><label htmlFor="minutes">Minutes</label><input id="minutes" name="minutes" type="number" min="5" max="240" required /><button type="submit">Add session</button></form><ul>{sessions.map(s=><li key={s.id}>{s.topic} — {s.minutes} minutes</li>)}</ul></main>;
}

